   124  /*
   125   * swap a short
   126   */
   127  static uint16_t
   128  _cdf_tole2(uint16_t sv)
   129  {
   130          uint16_t rv;
   131          uint8_t *s = RCAST(uint8_t *, RCAST(void *, &sv));
   132          uint8_t *d = RCAST(uint8_t *, RCAST(void *, &rv));
   133          d[0] = s[1];
   134          d[1] = s[0];
   135          return rv;
   136  }
   137
   138  /*
   139   * swap an int
   140   */
   141  static uint32_t
   142  _cdf_tole4(uint32_t sv)
   143  {
   144          uint32_t rv;
   145          uint8_t *s = RCAST(uint8_t *, RCAST(void *, &sv));
   146          uint8_t *d = RCAST(uint8_t *, RCAST(void *, &rv));
   147          d[0] = s[3];
   148          d[1] = s[2];
   149          d[2] = s[1];
   150          d[3] = s[0];
   151          return rv;
   152  }
   153
   154  /*
   155   * swap a quad
   156   */
   157  static uint64_t
   158  _cdf_tole8(uint64_t sv)
   159  {
   160          uint64_t rv;
   161          uint8_t *s = RCAST(uint8_t *, RCAST(void *, &sv));
   162          uint8_t *d = RCAST(uint8_t *, RCAST(void *, &rv));
   163          d[0] = s[7];
   164          d[1] = s[6];
   165          d[2] = s[5];
   166          d[3] = s[4];
   167          d[4] = s[3];
   168          d[5] = s[2];
   169          d[6] = s[1];
   170          d[7] = s[0];
   171          return rv;
   172  }
