   209  void
   210  cdf_swap_header(cdf_header_t *h)
   211  {
   212          size_t i;
   213
   214          h->h_magic = CDF_TOLE8(h->h_magic);
   215          h->h_uuid[0] = CDF_TOLE8(h->h_uuid[0]);
   216          h->h_uuid[1] = CDF_TOLE8(h->h_uuid[1]);
   217          h->h_revision = CDF_TOLE2(h->h_revision);
   218          h->h_version = CDF_TOLE2(h->h_version);
   219          h->h_byte_order = CDF_TOLE2(h->h_byte_order);
   220          h->h_sec_size_p2 = CDF_TOLE2(h->h_sec_size_p2);
   221          h->h_short_sec_size_p2 = CDF_TOLE2(h->h_short_sec_size_p2);
   222          h->h_num_sectors_in_sat = CDF_TOLE4(h->h_num_sectors_in_sat);
   223          h->h_secid_first_directory = CDF_TOLE4(h->h_secid_first_directory);
   224          h->h_min_size_standard_stream =
   225              CDF_TOLE4(h->h_min_size_standard_stream);
   226          h->h_secid_first_sector_in_short_sat =
   227              CDF_TOLE4(CAST(uint32_t, h->h_secid_first_sector_in_short_sat));
   228          h->h_num_sectors_in_short_sat =
   229              CDF_TOLE4(h->h_num_sectors_in_short_sat);
   230          h->h_secid_first_sector_in_master_sat =
   231              CDF_TOLE4(CAST(uint32_t, h->h_secid_first_sector_in_master_sat));
   232          h->h_num_sectors_in_master_sat =
   233              CDF_TOLE4(h->h_num_sectors_in_master_sat);
   234          for (i = 0; i < __arraycount(h->h_master_sat); i++) {
   235                  h->h_master_sat[i] =
   236                      CDF_TOLE4(CAST(uint32_t, h->h_master_sat[i]));
   237          }
   238  }
